def _fact(concept, answer, distractors, scenario, scenario_answer, scenario_distractors):
    return {
        'concept': concept,
        'answer': answer,
        'distractors': distractors,
        'scenario': scenario,
        'scenario_answer': scenario_answer,
        'scenario_distractors': scenario_distractors,
    }


def _questions(facts):
    questions = []
    for fact in facts:
        variants = [
            (f"Which statement best describes {fact['concept']}?",
             fact['answer'], fact['distractors']),
            (fact['scenario'], fact['scenario_answer'], fact['scenario_distractors']),
            (f"Which practice is most appropriate when working with {fact['concept']}?",
             fact['answer'], fact['distractors']),
        ]
        for text, answer, distractors in variants:
            options = [answer] + list(distractors)
            rotation = len(questions) % 4
            options = options[rotation:] + options[:rotation]
            questions.append({
                'question_text': text,
                'options': options,
                'correct_option': 'ABCD'[options.index(answer)],
                'explanation': f"{answer} is correct because it is the defining practical idea for {fact['concept']}.",
                'order_index': len(questions),
            })
    return questions


