def _merge_topic_pair(topics, first_name, second_name, merged_name):
    first_index = next(index for index, item in enumerate(topics) if item[0] == first_name)
    second_index = next(index for index, item in enumerate(topics) if item[0] == second_name)
    first_facts = topics[first_index][1][:5]
    second_facts = topics[second_index][1][:5]
    merged = (merged_name, first_facts + second_facts)
    return [
        item for index, item in enumerate(topics)
        if index not in {first_index, second_index}
    ] + [merged]


TOPICS = _merge_topic_pair(
    TOPICS,
    'Generative AI Fundamentals',
    'AI, Machine Learning, and Generative AI',
    'AI Foundations and Generative Models',
)
TOPICS = _merge_topic_pair(
    TOPICS,
    'Generation Controls and Hallucinations',
    'Evaluation, Reliability, and Quality',
    'Generation Controls, Reliability, and Evaluation',
)
TOPICS = _merge_topic_pair(
    TOPICS,
    'AI Agents and Tool Calling',
    'Real-world Generative AI Applications',
    'Agents and Real-world Applications',
)


def seed_generative_ai_quizzes():
    course = Course.query.filter_by(name='Generative AI').first()
    if not course:
        raise RuntimeError('Generative AI course does not exist.')
    mentor = User.query.filter_by(role='mentor_admin').first()
    existing = course.quizzes.all()
    expected_titles = {f'Quiz {day}' for day in range(1, 16)}
    existing_questions = [question.question_text for quiz in existing for question in quiz.questions.all()]
    if (len(existing) != 15 or {quiz.title for quiz in existing} != expected_titles or
            any(quiz.questions.count() != 30 for quiz in existing) or
            len(existing_questions) != len(set(existing_questions))):
        for quiz in existing:
            db.session.delete(quiz)
        db.session.flush()

    for day_number, (topic, facts) in enumerate(TOPICS, start=1):
        quiz = Quiz.query.filter_by(course_id=course.id, title=f'Quiz {day_number}').first()
        if quiz and quiz.questions.count() == 30:
            continue
        if quiz:
            db.session.delete(quiz)
            db.session.flush()
        quiz = Quiz(
            title=f'Quiz {day_number}', description=topic,
            course_id=course.id, day_number=day_number,
            time_limit_minutes=0, total_marks=30,
            status='published', created_by=mentor.id if mentor else None,
        )
        db.session.add(quiz)
        db.session.flush()
        for question in _questions(facts):
            db.session.add(QuizQuestion(
                quiz_id=quiz.id,
                question_text=question['question_text'],
                option_a=question['options'][0],
                option_b=question['options'][1],
                option_c=question['options'][2],
                option_d=question['options'][3],
                correct_option=question['correct_option'],
                explanation=question['explanation'],
                marks=1, order_index=question['order_index'],
            ))
    db.session.commit()
